export type Recipe = {
  id: string;
  title: string;
  description: string;
  time: number;
  difficulty: "Easy" | "Medium";
  category: string;
  ingredients: string[];
  staples: string[];
  accent: string;
  steps: string[];
};

function recipe(
  id: string,
  title: string,
  description: string,
  time: number,
  difficulty: "Easy" | "Medium",
  category: string,
  ingredients: string[],
  staples: string[],
  accent: string,
  steps: string[],
): Recipe {
  return { id, title, description, time, difficulty, category, ingredients, staples, accent, steps };
}

